def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = []
    op = []
    op_c = 0
    my_c = 0
    for h in history:
        m = h[0]
        o = h[1]
        my.append(m)
        op.append(o)
        if o == 'C':
            op_c += 1
        if m == 'C':
            my_c += 1

    op_d = n - op_c
    my_d = n - my_c
    last_opp = op[-1]
    last_me = my[-1]

    streak_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            streak_d += 1
        else:
            break

    r = min(8, n)
    recent8_d = 0
    for i in range(n - r, n):
        if op[i] == 'D':
            recent8_d += 1

    r6 = min(6, n)
    recent6_d = 0
    for i in range(n - r6, n):
        if op[i] == 'D':
            recent6_d += 1

    if n >= 2 and op_c == 0:
        return 'D'

    if n >= 6 and op_d >= n - 1:
        return 'D'

    if n >= 5:
        if (recent6_d >= 5 or recent8_d >= 6 or streak_d >= 4 or
                op_d * 10 >= n * 7):
            return 'D'

    if n >= 6 and op_d * 2 >= n:
        return 'D'

    if op_d == 0:
        forgiven = False
        for i in range(1, n):
            if history[i - 1][0] == 'D' and history[i][1] == 'C':
                forgiven = True
                break
        if my_d == 0:
            return 'D' if n >= 10 else 'C'
        if forgiven:
            return 'D'
        return 'C'

    if last_opp == 'C':
        return 'C'

    if last_me == 'D':
        return 'C'

    if n >= 2 and my[-2] == 'D':
        return 'C'

    return 'D'
